import {
  boolean,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';

import { usersTable } from './user';

export const NOTIFICATION_TYPES = [
  'lead_created',
  'course_created',
  'post_created',
  'post_published',
  'order_paid',
  'admin_broadcast',
] as const;

export type NotificationType = (typeof NOTIFICATION_TYPES)[number];

/** 'system' = auto-generated by app events; 'admin' = sent via composer. */
export const NOTIFICATION_SOURCES = ['system', 'admin'] as const;
export type NotificationSource = (typeof NOTIFICATION_SOURCES)[number];

export const notificationsTable = pgTable(
  'notifications',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    type: varchar('type', { length: 50 }).notNull(),
    title: varchar('title', { length: 255 }).notNull(),
    body: text('body'),
    href: varchar('href', { length: 500 }),
    entityId: varchar('entity_id', { length: 64 }),
    isRead: boolean('is_read').notNull().default(false),
    source: varchar('source', { length: 20 }).notNull().default('system'),
    createdByUserId: integer('created_by_user_id').references(
      () => usersTable.id,
      { onDelete: 'set null' },
    ),
    audienceLabel: varchar('audience_label', { length: 100 }),
    createdAt: timestamp('created_at').notNull().defaultNow(),
  },
  (table) => [
    index('idx_notifications_created_at').on(table.createdAt),
    index('idx_notifications_is_read').on(table.isRead),
    index('idx_notifications_type').on(table.type),
    index('idx_notifications_source').on(table.source),
  ],
);

export type Notification = typeof notificationsTable.$inferSelect;
export type NewNotification = typeof notificationsTable.$inferInsert;
